########## TLDR/.claudinite/local/packs/tldr/comment-class-menu.mjs
import { finding } from '../../../shared/engine/checks/helpers/findings.mjs';
import { classificationLine, classesIn } from '../../../shared/engine/checks/helpers/session-transcript.mjs';

// The testable half of RULES.md's "Put the `Comment class:` line on its own
// line": the classifier reads the WHOLE classification line and adds EVERY class
// token it finds (`classesIn()` matches globally), so the natural-sounding
//     Comment class: other — not a correction, feature request, or process-change
// declares all four classes, not `other`. The stray `feature` then arms
// `feature-requirements-first` BLOCKING against whatever commits the branch
// carries, even when the session never touched a product feature.
//
// This asserts the MANDATED FORM, not the author's intent. The prose tells the
// agent to write the class alone and put any explanation on the next line, so
// the line either is that or it is not — a question every character of it
// answers. An earlier draft chased intent instead, firing only on a class token
// that followed a negation word from a hand-picked list ("not", "never",
// "besides", …). That is unbounded in the wrong direction: the harm comes from a
// class token being PRESENT, and prose smuggles them in without negating
// anything. Probed against the real helper, that draft stayed silent on
//     Comment class: other — unrelated to any feature request      (declares feature)
//     Comment class: other, setting the feature question aside     (declares feature)
//     Comment class: correction | feature | process-change | other (declares all four)
// — the last a verbatim paste of the menu out of the classifier's own prompt,
// i.e. the likeliest way this bug is reproduced, missed by the check named for
// it. Checking the form catches all three and needs no word list, because a
// conforming line has nowhere to hide a token.
//
// A genuinely mixed comment stays legal and stays silent: it names each part it
// really is, positively, on that one line (`Comment class: correction,
// process-change`). Whether four comma-separated classes are "honest" is exactly
// the intent judgment this rule refuses to make — the form is respected, so the
// classifier does what the line asked.
//
// ADVISORY, deliberately, where the underlying defect is blocking-grade: the
// transcript is append-only, so by the time this is observable the declaration
// cannot be retracted. A blocking finding could never converge — it would spend
// the session's Stop cycles on something no edit can fix, which is precisely the
// waste the lesson records. Its job is to name the cause the moment it appears
// so the session doesn't re-derive it from an unexplained
// `feature-requirements-first` failure.

// One class token, spelled as the classifier's own alternation spells it, so
// this check models what `classesIn()` sees rather than a second opinion of it.
const CLASS = String.raw`(?:correction|feature|process[\s-]change|other)`;
// The mandated form: class tokens joined by a declaration separator, nothing
// else. `|` is deliberately NOT a separator — it is how the prompt renders the
// menu, so pasting the menu verbatim fails this pattern rather than reading as
// a four-class declaration.
const CONFORMING_RE = new RegExp(String.raw`^\s*${CLASS}(?:\s*(?:,|&|\+|and)\s*${CLASS})*\s*\.?\s*$`, 'i');

const rule = {
  id: 'tldr/comment-class-menu',
  severity: 'advisory',
  description: 'The `Comment class:` line must carry the class alone — every class token on it is declared, however the line phrases them',
  doc: '.claudinite/local/packs/tldr/RULES.md',
  scope: 'work',
  why: 'the classifier adds every class token on the classification line, so any explanation sharing that line declares the classes it mentions — a stray `feature` arms feature-requirements-first BLOCKING against the branch even when no product feature was touched',

  run(work) {
    // Only the latest owner turn is judged, for the same reason
    // comment-classification judges only that one: the transcript is
    // append-only, so an earlier turn's line was already reported at its own
    // Stop and can never converge.
    const turn = work.conversation().ownerTurns().last();
    if (!turn.exists) return [];
    const line = classificationLine(turn.reply());
    // No classification line at all is comment-classification's finding, not this one.
    if (!line) return [];

    // Everything after the `Comment class:` colon — the prefix cannot contain
    // one (the helper's pattern forbids it), so the first colon is the split.
    const declaration = line.slice(line.indexOf(':') + 1);
    if (CONFORMING_RE.test(declaration)) return [];

    const declared = [...classesIn(declaration)].sort();
    // A line naming no class at all is unclassified — comment-classification's
    // finding, not this one.
    if (!declared.length) return [];

    const arms = declared.includes('feature')
      ? ', including `feature`, which arms `feature-requirements-first` BLOCKING against this branch'
      : '';

    return [finding(rule, {
      file: '(conversation)',
      what: `the \`Comment class:\` line carries more than the class it means, so the classifier reads it as declaring ${declared.map((c) => `\`${c}\``).join(', ')}${arms}`,
      fix: 'write the class alone on its own line — `Comment class: other` — and put any explanation on the NEXT line; a genuinely mixed comment names each part it really is, comma-separated, on that one line. The transcript is append-only, so re-declaring cleanly on a later line does not override this one — do not retry, and expect the declared classes\' rules to fire on this branch',
    })];
  },
};

export default rule;
########## TLDR/.claudinite/local/packs/tldr/comment-class-menu.test.mjs
// See-it-fail fixture for tldr/comment-class-menu: a line carrying anything
// beyond the class it names must produce exactly one finding, and every
// conforming shape must produce none.
//
// The fixture drives the rule through the engine's own dispatch seam (runRule +
// buildContext with a transcript path), not by hand-rolling a work object — so
// the test proves the rule as the Stop hook actually runs it.
//
// Run it directly (no npm script owns .claudinite/local/packs):
//   node --test .claudinite/local/packs/tldr/comment-class-menu.test.mjs

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { mkdtempSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join, resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

import rule from './comment-class-menu.mjs';
import { buildContext } from '../../../shared/engine/checks/helpers/repo-context.mjs';
import { runRule } from '../../../shared/engine/checks/helpers/work.mjs';

const repoRoot = resolve(dirname(fileURLToPath(import.meta.url)), '..', '..', '..', '..');
const scratch = mkdtempSync(join(tmpdir(), 'tldr-comment-class-'));

// A minimal Claude Code transcript: one owner turn, then the assistant reply
// whose classification line is under test. These are the shapes
// session-transcript.mjs reads (a plain-string user message, an assistant
// content array of text blocks).
function transcriptWith(replyText) {
  const entries = [
    { type: 'user', timestamp: '2026-07-31T00:00:00Z', message: { role: 'user', content: 'please look at the release job' } },
    { type: 'assistant', timestamp: '2026-07-31T00:00:01Z', message: { role: 'assistant', content: [{ type: 'text', text: replyText }] } },
  ];
  const path = join(scratch, `t-${Math.random().toString(36).slice(2)}.jsonl`);
  writeFileSync(path, `${entries.map((e) => JSON.stringify(e)).join('\n')}\n`);
  return path;
}

const findingsFor = (replyText) =>
  runRule(rule, buildContext({ root: repoRoot, mode: 'changed', transcriptPath: transcriptWith(replyText) }));

test('fires on the menu-restating line that poisoned the 2026-07-26 sessions', () => {
  const found = findingsFor('Comment class: other — not a correction, feature request, or process-change\n\nOn it.');
  assert.equal(found.length, 1);
  assert.equal(found[0].rule, 'tldr/comment-class-menu');
  assert.equal(found[0].severity, 'advisory');
  // Every class the classifier actually reads off the line is named back.
  for (const declared of ['correction', 'feature', 'process-change', 'other']) {
    assert.match(found[0].what, new RegExp(declared), `finding should name the declared class ${declared}`);
  }
});

// The three cases below are why this rule checks the form instead of hunting a
// negation word: each declares a class in plain prose, negating nothing, and an
// intent-inferring draft of this rule stayed silent on all three.

test('fires on a stray class smuggled in without negating anything', () => {
  const found = findingsFor('Comment class: other — unrelated to any feature request\n\nProceeding.');
  assert.equal(found.length, 1);
  assert.match(found[0].what, /feature/);
  // `feature` is the one that arms a BLOCKING rule, so the finding says so.
  assert.match(found[0].what, /feature-requirements-first/);
});

test('fires on a class named while being set aside', () => {
  const found = findingsFor('Comment class: other, setting the feature question to one side');
  assert.equal(found.length, 1);
  assert.match(found[0].what, /feature/);
});

test('fires on the menu pasted verbatim out of the prompt', () => {
  const found = findingsFor('Comment class: correction | feature | process-change | other');
  assert.equal(found.length, 1);
  // `|` is the menu's separator, never a declaration separator.
  assert.match(found[0].what, /correction/);
  assert.match(found[0].what, /feature/);
});

test('fires on an explanation sharing the line even when it smuggles no class', () => {
  const found = findingsFor('Comment class: correction — fixed the typo');
  assert.equal(found.length, 1);
  assert.match(found[0].what, /correction/);
  // Nothing armed a blocking rule here, so the finding does not claim otherwise.
  assert.doesNotMatch(found[0].what, /feature-requirements-first/);
});

test('silent on the class declared alone', () => {
  assert.deepEqual(findingsFor('Comment class: other\n\nNot a correction, feature request, or process-change — just a note.'), []);
});

test('silent on an honest multi-class declaration', () => {
  assert.deepEqual(findingsFor('Comment class: correction, process-change\n\nFixing it and updating the procedure.'), []);
});

test('silent on a multi-class declaration joined by "and"', () => {
  assert.deepEqual(findingsFor('Comment class: correction and process-change'), []);
});

test('silent on a trailing period', () => {
  assert.deepEqual(findingsFor('Comment class: other.'), []);
});

test('silent when there is no classification line at all (comment-classification owns that)', () => {
  assert.deepEqual(findingsFor('Sure, doing that now.'), []);
});

test('silent when the line names no known class at all (comment-classification owns that)', () => {
  assert.deepEqual(findingsFor('Comment class: misc'), []);
});
########## TLDR/.claudinite/local/packs/tldr/release-root-version-align.mjs
import { finding } from '../../../shared/engine/checks/helpers/findings.mjs';

// `.github/workflows/chrome-extension-daily-release.yml` is VENDORED from the
// chrome-extension-release pack, and this repo's copy is deliberately NOT
// byte-identical to that stub: #241 added a step to the `bump` job that aligns
// the repo-root package.json to the bumped version inside the same commit. It is
// load-bearing — the release config only bumps `manifest_path` and
// `package_json_path`, so without it the root file falls behind after every
// daily release and both the `sharedConstants` version entry in
// .claudinite-checks.json and `cer/version-sync` go BLOCKING.
//
// The delta is fragile in a specific, repeating way: the pack's
// `chrome-release-vendoring` migration MATERIALIZES this path — an unconditional
// verbatim overwrite from the stub, with no per-repo exemption seam (unlike a
// check finding, which .claudinite-checks.json can `accept`). Baselining
// re-attempts that write every cycle, so any agent that lands the withheld file
// mechanically deletes the step and silently re-opens the drift #241 closed.
// Issue #245 is the open decision on the real fix (teach release.config the root
// file, or give materialize an extension point); until it lands, this check is
// what makes the deletion loud instead of silent. When #245 resolves, delete
// this rule with the step.
//
// It keys on the BEHAVIOUR, not the step's label: the align step is the only
// place the workflow names the repo-root `package.json` as a literal file, since
// the stub reaches the two release-config paths through
// `${{ steps.cfg.outputs.* }}` only. So renaming or rewording the step keeps
// this silent, and only actually dropping the root-file write fires it.
const WORKFLOW = '.github/workflows/chrome-extension-daily-release.yml';

// The quoted literal the align step's inline node script reads and writes.
const ROOT_PACKAGE_JSON = /(["'])package\.json\1/;

const rule = {
  id: 'tldr/release-root-version-align',
  severity: 'blocking',
  description: "The daily-release workflow must keep aligning the repo-root package.json to the bumped version — it is this repo's local delta over the vendored stub",
