########## on-device-privacy/no-listener.mjs
// "There is no server either" as a check: the app accepts no inbound
// connection. Scans the app's sources (`mac/Sources/`) for the APIs that open a
// *listening* socket, and for the server frameworks a dashboard would arrive on.
//
// The rule has history. A web dashboard did once exist, in the Python reference,
// and it was removed on purpose along with the reference itself — a listener is
// a decision about who may read the laugh log, and the log is the room's memory.
// That is why reintroducing one is gated on the owner's sign-off, a loopback-only
// default and an auth/CSRF story (the finding's `fix` says so), rather than being
// a feature someone adds on the way past.
//
// Its sibling `no-network-client` covers the outbound half, and earlier sweeps
// read that as covering this half too — a Network-framework `NWListener` needs
// `import Network`, which that check already bans. True, but not the whole
// surface: a listener does not have to come through the Network framework.
// `socket(2)` is reachable from plain `import Foundation` (Darwin is re-exported),
// `NSXPCListener`, `CFSocket*` and `NSSocketPort` are Foundation types, and an
// embedded HTTP server (Vapor, SwiftNIO, Swifter, GCDWebServer) arrives as an
// import, not as `import Network`. None of those trip `no-network-client`. This
// check closes that gap.
//
// Deliberately NOT banned: a bare `listen(`. This is an app whose whole domain
// vocabulary is listening — `requestListening()`, `finishListening()`, `private
// var listening` — and a mic-listening method named `listen()` is a false alarm
// waiting to happen. It costs nothing to drop: BSD sockets are created before
// they are listened on, so `socket(` catches the same code one line earlier, and
// "socket" carries no microphone meaning here. A fixture pins the vocabulary.
//
// Dependency-free by design (a local pack must load without the canon mount),
// so the finding object is built by hand rather than via the engine helper.

const LISTENERS = [
  [/\bNWListener\b/, 'NWListener (a Network-framework listener)'],
  [/\bNSXPCListener\b/, 'NSXPCListener'],
  [/\bCFSocket[A-Za-z]*\s*\(/, 'a CFSocket API'],
  [/\b(?:NS)?SocketPort\b/, 'SocketPort'],
  // The BSD socket primitive. Creating one precedes both listen(2) and
  // connect(2), so this catches a hand-rolled server (and a hand-rolled client).
  [/\bsocket\s*\(/, 'socket(2)'],
  // An embedded HTTP server, which arrives as a package import rather than as
  // anything in the Network framework.
  [
    /^\s*import\s+(?:Vapor|NIO[A-Za-z]*|Swifter|Telegraph|Hummingbird|Kitura[A-Za-z]*|Perfect[A-Za-z]*|FlyingFox|Embassy|GCDWebServer|Criollo)\b/,
    'an embedded HTTP server framework',
  ],
];

const inScope = (f) => f.startsWith('mac/Sources/') && f.endsWith('.swift');

const rule = {
  id: 'on-device-privacy/no-listener',
  severity: 'blocking',
  description: 'No inbound listener — no socket, XPC listener or embedded HTTP server (mac/Sources/)',
  doc: '.claudinite/local/packs/on-device-privacy/RULES.md',
  why: 'a listener exposes the laugh log to whatever can reach the port — reintroducing one is a decision about who may read the room, not a feature',

  run(ctx) {
    const out = [];
    for (const file of ctx.files.filter(inScope)) {
      const text = ctx.read(file);
      if (text === null) continue;
      const lines = text.split('\n');
      for (let i = 0; i < lines.length; i += 1) {
        for (const [pattern, what] of LISTENERS) {
          if (!pattern.test(lines[i])) continue;
          out.push({
            rule: rule.id,
            severity: rule.severity,
            file,
            line: i + 1,
            what: `${what} in the app (${file})`,
            why: rule.why,
            fix: "drop the listener; a dashboard, metrics port or remote-control API needs the owner's explicit sign-off, a loopback-only default and an auth/CSRF story written into RULES.md before any of it is written in Swift",
            doc: rule.doc,
          });
          break;
        }
      }
    }
    return out;
  },
};

export default rule;
########## on-device-privacy/no-network-client.mjs
// The privacy boundary as a check: the always-on capture path may not open an
// outbound connection. Scans the app's sources (`mac/Sources/`) for network
// *client* APIs. It matches call/import tokens rather than URL strings, so a
// comment mentioning a URL stays legal while an actual client does not.
//
// Since the Python reference was removed there is exactly one runtime tree and
// **no accepted egress at all** — detection (Sound Analysis) and speech
// recognition are both on-device, and nothing downloads a model. That makes this
// check absolute: any hit is a finding, with no optional-extra carve-out to
// reason about.
//
// Dependency-free by design (a local pack must load without the canon mount),
// so the finding object is built by hand rather than via the engine helper.

const SWIFT_CLIENTS = [
  [/\bURLSession\b/, 'URLSession'],
  [/\bNSURLConnection\b/, 'NSURLConnection'],
  [/^\s*import\s+Network\b/, 'the Network framework'],
  [/\bNWConnection\b/, 'NWConnection'],
];

const inScope = (f) => f.startsWith('mac/Sources/') && f.endsWith('.swift');

const rule = {
  id: 'on-device-privacy/no-network-client',
  severity: 'blocking',
  description: 'No outbound network client in the always-on capture path (mac/Sources/)',
  doc: '.claudinite/local/packs/on-device-privacy/RULES.md',
  why: "the product's headline promise is that the room's audio never leaves the machine — a client in the capture path is how that promise breaks",

  run(ctx) {
    const out = [];
    for (const file of ctx.files.filter(inScope)) {
      const text = ctx.read(file);
      if (text === null) continue;
      const lines = text.split('\n');
      for (let i = 0; i < lines.length; i += 1) {
        for (const [pattern, what] of SWIFT_CLIENTS) {
          if (!pattern.test(lines[i])) continue;
          out.push({
            rule: rule.id,
            severity: rule.severity,
            file,
            line: i + 1,
            what: `${what} in the capture path (${file})`,
            why: rule.why,
            fix: 'keep analysis on-device — drop the client; the app has no accepted egress, so adding one is a product decision that belongs in RULES.md first',
            doc: rule.doc,
          });
          break;
        }
      }
    }
    return out;
  },
};

export default rule;
########## on-device-privacy/on-device-speech.mjs
// The "I just laughed" voice command runs through Apple's Speech framework,
// which streams audio to Apple's servers unless the request opts out — so every
// SFSpeechAudioBufferRecognitionRequest the app builds must set
// requiresOnDeviceRecognition (VoiceCommand.swift:48, "never leaves the Mac";
// DESIGN §3/§6, and the Info.plist usage string promises the same to the user).
// Dependency-free (a local pack loads without the canon mount): plain findings.

const rule = {
  id: 'on-device-privacy/on-device-speech',
  severity: 'blocking',
  description: 'Every SFSpeech recognition request must set requiresOnDeviceRecognition',
  doc: '.claudinite/local/packs/on-device-privacy/RULES.md',
  why: "Speech defaults to server-side recognition, which would ship living-room audio to Apple — the opposite of what the app's mic prompt promises",

  run(ctx) {
    const out = [];
    for (const file of ctx.files.filter((f) => f.startsWith('mac/Sources/') && f.endsWith('.swift'))) {
      const text = ctx.read(file);
      if (text === null) continue;
      const lines = text.split('\n');
      for (let i = 0; i < lines.length; i += 1) {
        if (!/\bSFSpeechAudioBufferRecognitionRequest\s*\(/.test(lines[i])) continue;
        // The opt-out is set on the fresh request, near its construction — look
        // ahead a short window rather than requiring an exact line.
        const window = lines.slice(i, i + 12).join('\n');
        if (/requiresOnDeviceRecognition\s*=\s*true/.test(window)) continue;
        out.push({
          rule: rule.id,
          severity: rule.severity,
          file,
          line: i + 1,
          what: 'a speech recognition request is built without requiresOnDeviceRecognition = true',
          why: rule.why,
          fix: 'set requiresOnDeviceRecognition = true on the request right after constructing it',
          doc: rule.doc,
        });
      }
    }
    return out;
  },
};

export default rule;
########## edfringe/no-stray-package-json.mjs
// Dependency-free by design: a local pack's checks must load without the
// vendored mount, so this returns plain finding objects rather than importing
// engine/checks/helpers/findings.mjs.

// The pinned Node 22 detects a .js file's module syntax on its own — no
// package.json needed to mark a directory as ESM. `plan/package.json` predates
// that detection and stays only as a grandfathered no-op; it must not become a
// pattern copied into every new source directory.
const ALLOWED = new Set(['package.json', 'plan/package.json']);

const rule = {
  id: 'edfringe-no-stray-package-json',
  severity: 'advisory',
  description: 'No package.json exists outside the repo root and the grandfathered plan/package.json',
  why:
    'a package.json is not needed to mark a directory as ESM — the pinned Node 22 detects module syntax in a .js file on its own — so a new one is very likely a copy of the plan/ leftover rather than something that does anything',
  doc: 'RULES.md',

  run(ctx) {
    const stray = ctx.files.filter((f) => f.endsWith('/package.json') && !ALLOWED.has(f)).sort();
    if (stray.length === 0) return [];

    return stray.map((f) => finding(f,
      `${f} is not needed to mark its directory as ESM (node --check and the test suite already detect module syntax unaided) — remove it, unless it genuinely configures its own dependencies/scripts`,
    ));
  },
};

function finding(file, fix) {
  return {
    rule: rule.id,
    severity: rule.severity,
    file,
    line: null,
    what: `${file} is a package.json outside the repo root and plan/`,
    why: rule.why,
    fix,
    doc: rule.doc,
  };
}

export default rule;
########## vascular-coloring/rendered-overlays-untracked.mjs
// Rendered output lives under analysis/ (measure_vessels.py --overlays writes
// analysis/overlays/, annotate_overlays.py writes analysis/annotated/); both are
// gitignored and regenerated. The real source images live under references/.
const RENDER_ROOT = 'analysis/';
const IMAGE = /\.(png|jpe?g|tiff?|gif|bmp|webp)$/i;

const rule = {
  id: 'rendered-overlays-untracked',
  severity: 'blocking',
  description: 'No rendered overlay image is committed under analysis/',
  doc: '.claudinite/local/packs/vascular-coloring/RULES.md',
  why: 'an overlay PNG is a regenerable render, not data — committing one freezes a snapshot that silently stops matching the scripts, and the owner\'s rule is that only real data or an agreed ground-truth image gets committed',

  run(ctx) {
    return ctx.tracked
      .filter((f) => f.startsWith(RENDER_ROOT) && IMAGE.test(f))
      .map((f) => ({
        rule: rule.id,
        severity: rule.severity,
        file: f,
        line: null,
        what: `${f} is a tracked image under ${RENDER_ROOT}`,
        why: rule.why,
        fix: 'untrack it (git rm --cached) and regenerate with python3 analysis/measure_vessels.py --overlays or python3 analysis/annotate_overlays.py — commit the script and the numeric results instead; if the image really is data or agreed ground truth, put it under references/',
        doc: rule.doc,
      }));
  },
};

export default rule;
